const method = $('Webhook Clientes').first().json.method;
const csvData = $input.first().binary.data;
const csvText = Buffer.from(csvData, 'base64').toString('utf8');
const lines = csvText.trim().split('\n');
const headers = lines[0].split(',');

if (method === 'GET') {
  // --- GET ALL ---
  const data = lines.slice(1).map(line => {
    const values = line.split(',');
    const obj = {};
    headers.forEach((h, i) => obj[h.trim()] = values[i]?.trim() || '');
    return obj;
  });
  return [data.map(item => ({ json: item }))]; // Output 1

} else if (method === 'POST') {
  // --- UPDATE/CREATE ---
  // Assuming body contains unique identifier (telefono)
  const body = $('Webhook Clientes').first().json.body;
  const targetPhone = body.telefono || body.cliente_telefono;

  let found = false;
  const newLines = lines.map((line, index) => {
    if (index === 0) return line; // Header
    const cols = line.split(',');
    // 3rd column is telefono (index 2) based on: id,nombre,telefono,...
    // Adjust based on actual CSV structure. Let's map it dynamically.
    const rowObj = {};
    headers.forEach((h, i) => rowObj[h.trim()] = cols[i]?.trim() || '');

    if (rowObj.telefono === targetPhone) {
        // Merge updates
        found = true;
        return headers.map(h => body[h] !== undefined ? body[h] : rowObj[h]).join(',');
    }
    return line;
  });

  if (!found && body.telefono) {
      // Append new if not found (simple Append logic)
      // Generate ID if needed
      const newId = lines.length;
      const newRow = headers.map(h => {
          if (h === 'id') return newId;
          return body[h] || '';
      }).join(',');
      newLines.push(newRow);
  }

  const newCsv = newLines.join('\n');

  return [// Output 2 (Post-Write)
      {
        json: { success: true, updated: found },
        binary: {
            data: Buffer.from(newCsv).toString('base64'),
            mimeType: 'text/csv',
            fileExtension: 'csv',
            fileName: 'clientes.csv'
        }
      }
  ];
}
